#include <Adafruit_NeoPixel.h>

#define MATRIX_PIN 6
#define MATRIX_SIZE 64

Adafruit_NeoPixel matrix(MATRIX_SIZE, MATRIX_PIN,
NEO_GRB + NEO_KHZ800);

uint16_t offset = 0;
uint8_t pattern = 0;

void setup() {
  Serial.begin(115200);

  matrix.begin();
  matrix.setBrightness(60);
  matrix.show();
}

void loop() {

  for (int i = 0; i < MATRIX_SIZE; i++) {

    int row = i / 8;
    int col = i % 8;

    uint16_t hue;

    if (pattern == 0) {
// Horizontal
      hue = offset + col * 8192;
    }

    else if (pattern == 1) {
// Vertical
      hue = offset + row * 8192;
    }

    else if (pattern == 2) {
// Diagonal
      hue = offset + (row + col) * 4000;
    }

    else if (pattern == 3) {
// Circular
      float dx = col - 3.5;
      float dy = row - 3.5;

      float angle = atan2(dy, dx);

      hue = (uint16_t)(
      (angle + PI) * 65535.0 / (2.0 * PI)
      );

      hue += offset;
    }

    else {
// Plasma
      uint8_t w1 = sin8(col * 32 + offset / 4);
      uint8_t w2 = sin8(row * 32 + offset / 3);
      uint8_t w3 = sin8((row + col) * 32 + offset / 5);

      hue = offset +
      (uint16_t)w1 * 128 +
      (uint16_t)w2 * 128 +
      (uint16_t)w3 * 128;
    }

    matrix.setPixelColor(
    i,
    matrix.ColorHSV(hue, 255, 255)
    );
  }

  matrix.show();

  offset += 300;
  delay(30);

// Change pattern every ~10 seconds
  static unsigned long lastChange = 0;

  if (millis() - lastChange > 10000) {
    lastChange = millis();

    pattern++;

    if (pattern > 4) {
      pattern = 0;
    }

    Serial.print("Rainbow Pattern: ");
    Serial.println(pattern);
  }
}
